style.css:
/* Global rainbow ring cursor — encoded for Stylish */
/* Default (1x / standard displays) */
html, body, * {
  cursor: url("data:image/svg+xml;base64,") 32 32, auto !important;
}

/* Retina / HiDPI (2x and up) — larger asset */
@media (min-resolution: 2dppx) {
  html, body, * {
    cursor: url("data:image/svg+xml;base64,") 64 64, auto !important;
  }
}
